"""Generate docs/data-quality-rules.md and docs/data-dictionary.md from code and a local run.

Run after `python -m mfgops.run_local`:
    python tools/gen_docs.py
"""

from pathlib import Path

import pandas as pd

from mfgops.ingest import CONTRACTS
from mfgops.quality import RULES

out = Path("docs")
lines = [
    "# Data-quality rules",
    "",
    "Generated from `src/mfgops/quality.py` by `tools/gen_docs.py`. Do not edit by hand.",
    "",
    "| Rule | Table | Dimension | Severity | Check | Owner | Corrective action |",
    "|---|---|---|---|---|---|---|",
]
for r in RULES:
    lines.append(
        f"| {r.rule_id} | {r.table} | {r.dimension} | {r.severity} | {r.description} | {r.owner} | {r.action} |"
    )
lines += [
    "",
    "Plus the checks outside the rule engine:",
    "",
    "| Check | Where | Effect |",
    "|---|---|---|",
    "| Source contract (file exists, exact columns, not empty) | `ingest.validate_sources` | Run fails before loading |",
    "| Row count vs last successful run (warn ±30%, fail −50%) | `orchestrate.monitor_row_counts` | Warning or failed run |",
    "| Error rate per table above 2% | `orchestrate` quality gate | Gold not refreshed |",
    "| Silver vs gold totals, KPI recalculation | `reconcile.reconcile` | Failed run |",
]
(out / "data-quality-rules.md").write_text("\n".join(lines) + "\n")

lake = Path("lakehouse/gold")
dd = [
    "# Data dictionary",
    "",
    "Generated by `tools/gen_docs.py` from the gold Parquet tables of a local run (seed 42, full load plus the 15 Nov 2026 change extract). All data is synthetic.",
    "",
]
grain = {
    "fact_sales_order_line": "one row per sales order line",
    "fact_production_order": "one row per production order",
    "fact_inventory_snapshot": "one row per plant, material and weekly snapshot date",
    "fact_purchase_order": "one row per purchase order",
    "dim_date": "one row per calendar day, 2025–2026",
    "dim_plant": "one row per plant",
    "dim_material": "one row per material",
    "dim_customer": "one row per customer version (slowly changing dimension type 2), plus an Unknown member",
    "dim_supplier": "one row per supplier",
    "dim_work_center": "one row per work centre",
    "dq_results": "one row per rule per pipeline run",
    "security_plant_access": "one row per user and plant the user may see (row-level security)",
}
for t in sorted(p.name for p in lake.iterdir()):
    df = pd.read_parquet(lake / t)
    dd += [
        f"## {t}",
        "",
        f"Grain: {grain.get(t, '-')}. Rows: {len(df):,}.",
        "",
        "| Column | Type | Nulls % | Distinct | Example |",
        "|---|---|---|---|---|",
    ]
    for c in df.columns:
        s = df[c]
        ex = s.dropna().iloc[0] if s.notna().any() else ""
        dd.append(f"| {c} | {s.dtype} | {s.isna().mean() * 100:.1f} | {s.nunique():,} | {str(ex)[:30]} |")
    dd.append("")
dd += ["## Source contracts (D365-shaped extracts)", "", "| Table | Extract columns |", "|---|---|"]
dd += [f"| {k} | {', '.join(v)} |" for k, v in CONTRACTS.items()]
(out / "data-dictionary.md").write_text("\n".join(dd) + "\n")
print("docs written")
